  const esc = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  function slugFor(n) {
    const k = (n || '').toLowerCase();
    for (const [kw, slug] of MAP) {
      if (new RegExp('(^|[^a-z0-9])' + esc(kw) + '($|[^a-z0-9])').test(k)) return slug;
    }
    return null;
  }
  const slug = $derived(slugFor(name));
  const letter = $derived((name || '?').trim().charAt(0).toUpperCase() || '?');
</script>

{#if slug}
  <svg class="brandlogo" width={size} height={size} viewBox="0 0 24 24" role="img" aria-label={name}>{@html LOGOS[slug]}</svg>
{:else}
  <span class="brandlogo brandlogo--mono" aria-label={name} title={name}
    style={`width:${size}px;height:${size}px;font-size:${Math.max(9, Math.round(size * 0.5))}px`}>{letter}</span>
{/if}

<style>
  .brandlogo { flex: 0 0 auto; display: inline-block; color: #ececec; }
  .brandlogo--mono {
    display: inline-flex; align-items: center; justify-content: center;
    border-radius: 5px; background: var(--surface-3); border: 1px solid var(--border-strong);
    color: var(--fg-secondary); font-family: var(--font-display); font-weight: 600; line-height: 1;
    user-select: none;
  }
</style>
